import { resolveCountryConfig, supportedCountryOptions } from "../country/registry.js";

export const ADMIN_TAX_TYPES=Object.freeze(["GST","VAT","No Tax"]);
export function administrationCompanyFormModel(company={}){const config=resolveCountryConfig(company.country),taxType=ADMIN_TAX_TYPES.includes(company.taxType)?company.taxType:ADMIN_TAX_TYPES.includes(company.taxSystem)?company.taxSystem:ADMIN_TAX_TYPES.includes(company.tax_system)?company.tax_system:company.vatRegistered||company.vatStatus==="Registered"||company.trn?"VAT":company.gstRegistered||company.gstStatus==="Registered"||company.gstin?"GST":"No Tax",region=company.region||company.emirate||company.state||"",taxNumber=company.taxNumber||(taxType==="VAT"?company.trn:taxType==="GST"?company.gstin:"");return{country:config.country,countries:supportedCountryOptions(),regions:config.jurisdictions,businessTypes:config.businessTypes,region,taxType,taxNumber,businessRegistrationNumber:company.businessRegistrationNumber||company.registrationNumber||company.tradeLicenseNumber||"",currency:config.currency,timezone:company.timezone||config.defaults.timezone}}
export function normalizeAdministrationCompanyInput(data){const config=resolveCountryConfig(data.country),taxType=ADMIN_TAX_TYPES.includes(data.taxType)?data.taxType:"No Tax",taxNumber=taxType==="No Tax"?"":String(data.taxNumber||"").trim().toUpperCase(),region=String(data.region||"").trim();if(!config.jurisdictions.includes(region))throw Error(`Select a valid Region for ${config.countryName}`);if(taxType==="GST"&&taxNumber&&!resolveCountryConfig("IN").tax.validateIdentifier(taxNumber))throw Error("Enter a valid GSTIN");if(taxType==="VAT"&&taxNumber&&!resolveCountryConfig("AE").tax.validateIdentifier(taxNumber))throw Error("Enter a valid 15-digit TRN");if(taxType!=="No Tax"&&!taxNumber)throw Error("Tax Registration Number is required");const registration=String(data.businessRegistrationNumber||"").trim();return{...data,country:config.country,currency:config.currency,timezone:data.timezone||config.defaults.timezone,state:region,region,emirate:config.country==="AE"?region:"",taxType,taxSystem:taxType,tax_system:taxType,taxNumber,gstin:taxType==="GST"?taxNumber:"",trn:taxType==="VAT"?taxNumber:"",gstRegistered:taxType==="GST",vatRegistered:taxType==="VAT",gstStatus:taxType==="GST"?"Registered":"Unregistered",vatStatus:taxType==="VAT"?"Registered":"Unregistered",businessRegistrationNumber:registration,registrationNumber:config.country==="IN"?registration:data.registrationNumber||"",tradeLicenseNumber:config.country==="AE"?registration:data.tradeLicenseNumber||""}}
